import{_ as e,c as t,o as a,a0 as o}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Mental Game Introduction - Participant Guide","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/en/participant-guide.md","filePath":"public/downloads/en/participant-guide.md"}');const r=e({name:"public/downloads/en/participant-guide.md"},[["render",function(e,i,r,n,l,s){return a(),t("div",null,[...i[0]||(i[0]=[o('<h1 id="mental-game-introduction-participant-guide" tabindex="-1">Mental Game Introduction - Participant Guide <a class="header-anchor" href="#mental-game-introduction-participant-guide" aria-label="Permalink to &quot;Mental Game Introduction - Participant Guide&quot;">​</a></h1><p><strong>Pétanque Academy</strong><br><em>Elite Player Development</em></p><hr><h2 id="welcome" tabindex="-1">Welcome <a class="header-anchor" href="#welcome" aria-label="Permalink to &quot;Welcome&quot;">​</a></h2><p>Today you&#39;ll learn practical mental game techniques to improve your pétanque performance.</p><h3 id="what-you-ll-learn" tabindex="-1">What You&#39;ll Learn <a class="header-anchor" href="#what-you-ll-learn" aria-label="Permalink to &quot;What You&#39;ll Learn&quot;">​</a></h3><ul><li>Why mental training matters for elite players</li><li>The difference between &quot;technical mode&quot; and &quot;flow mode&quot;</li><li>How to recognize and manage your inner critic</li><li>Simple techniques for pressure management</li><li>A basic pre-shot routine</li></ul><hr><h2 id="the-zone-flow-state" tabindex="-1">The Zone / Flow State <a class="header-anchor" href="#the-zone-flow-state" aria-label="Permalink to &quot;The Zone / Flow State&quot;">​</a></h2><h3 id="what-is-flow" tabindex="-1">What is Flow? <a class="header-anchor" href="#what-is-flow" aria-label="Permalink to &quot;What is Flow?&quot;">​</a></h3><p>Flow is that magical state where:</p><ul><li>Everything feels effortless</li><li>Time seems to slow down</li><li>You&#39;re not thinking, just playing</li><li>Your technique executes perfectly</li></ul><h3 id="two-modes-of-mind" tabindex="-1">Two Modes of Mind <a class="header-anchor" href="#two-modes-of-mind" aria-label="Permalink to &quot;Two Modes of Mind&quot;">​</a></h3><p><strong>Planning Mode (Analytical)</strong></p><ul><li>Analyzing the terrain</li><li>Choosing your strategy</li><li>Deciding on the shot</li><li>Assessing risks</li></ul><p><strong>Execution Mode (Flow)</strong></p><ul><li>Trusting your body</li><li>Not thinking about technique</li><li>Present-moment focus</li><li>Automatic execution</li></ul><h3 id="the-switch" tabindex="-1">The Switch <a class="header-anchor" href="#the-switch" aria-label="Permalink to &quot;The Switch&quot;">​</a></h3><p>The key skill: <strong>switching from planning to execution mode</strong></p><p><strong>Before the shot:</strong> Analyze, plan, decide<br><strong>During the shot:</strong> Trust, flow, execute</p><hr><h2 id="the-inner-critic-vs-inner-coach" tabindex="-1">The Inner Critic vs Inner Coach <a class="header-anchor" href="#the-inner-critic-vs-inner-coach" aria-label="Permalink to &quot;The Inner Critic vs Inner Coach&quot;">​</a></h2><h3 id="your-inner-critic-says" tabindex="-1">Your Inner Critic Says: <a class="header-anchor" href="#your-inner-critic-says" aria-label="Permalink to &quot;Your Inner Critic Says:&quot;">​</a></h3><ul><li>&quot;That was terrible!&quot;</li><li>&quot;You always mess up under pressure&quot;</li><li>&quot;Everyone&#39;s watching you fail&quot;</li><li>&quot;You&#39;re not good enough&quot;</li></ul><h3 id="your-inner-coach-says" tabindex="-1">Your Inner Coach Says: <a class="header-anchor" href="#your-inner-coach-says" aria-label="Permalink to &quot;Your Inner Coach Says:&quot;">​</a></h3><ul><li>&quot;What can I learn from this?&quot;</li><li>&quot;Next shot, fresh start&quot;</li><li>&quot;I&#39;ve made this shot before&quot;</li><li>&quot;Trust the process&quot;</li></ul><h3 id="reframing-exercise" tabindex="-1">Reframing Exercise <a class="header-anchor" href="#reframing-exercise" aria-label="Permalink to &quot;Reframing Exercise&quot;">​</a></h3><p>When you notice your Inner Critic:</p><ol><li><strong>Pause</strong> - Recognize the critical thought</li><li><strong>Reframe</strong> - What would your coach say?</li><li><strong>Reset</strong> - Take 3 breaths</li><li><strong>Refocus</strong> - Next shot</li></ol><hr><h2 id="practical-tools" tabindex="-1">Practical Tools <a class="header-anchor" href="#practical-tools" aria-label="Permalink to &quot;Practical Tools&quot;">​</a></h2><h3 id="_3-breath-reset" tabindex="-1">3-Breath Reset <a class="header-anchor" href="#_3-breath-reset" aria-label="Permalink to &quot;3-Breath Reset&quot;">​</a></h3><p>Use this after mistakes or when feeling pressure:</p><ol><li><strong>Breath 1:</strong> Notice the tension (where do you feel it?)</li><li><strong>Breath 2:</strong> Release the tension (let it go)</li><li><strong>Breath 3:</strong> Refocus on now (this shot, this moment)</li></ol><h3 id="pre-shot-routine" tabindex="-1">Pre-Shot Routine <a class="header-anchor" href="#pre-shot-routine" aria-label="Permalink to &quot;Pre-Shot Routine&quot;">​</a></h3><p>Create consistency with a simple routine:</p><ol><li><strong>Visualize</strong> - See the shot in your mind</li><li><strong>Breathe</strong> - One deep breath</li><li><strong>Anchor</strong> - Touch your boule, feel the weight</li><li><strong>Execute</strong> - Trust and throw</li></ol><h3 id="mistake-recovery-protocol" tabindex="-1">Mistake Recovery Protocol <a class="header-anchor" href="#mistake-recovery-protocol" aria-label="Permalink to &quot;Mistake Recovery Protocol&quot;">​</a></h3><p>After a bad shot:</p><ol><li><strong>Acknowledge</strong> - &quot;That didn&#39;t go as planned&quot;</li><li><strong>Release</strong> - Physical reset (shake it off, walk)</li><li><strong>Refocus</strong> - &quot;Next shot is a new opportunity&quot;</li><li><strong>Execute</strong> - Trust your routine</li></ol><hr><h2 id="your-action-plan" tabindex="-1">Your Action Plan <a class="header-anchor" href="#your-action-plan" aria-label="Permalink to &quot;Your Action Plan&quot;">​</a></h2><h3 id="this-week" tabindex="-1">This Week <a class="header-anchor" href="#this-week" aria-label="Permalink to &quot;This Week&quot;">​</a></h3><p>Choose ONE technique to practice:</p><ul><li>[ ] 3-Breath Reset after every mistake</li><li>[ ] Pre-shot routine on every throw</li><li>[ ] Reframe one Inner Critic thought per session</li><li>[ ] Practice switching from planning to execution mode</li></ul><h3 id="track-your-progress" tabindex="-1">Track Your Progress <a class="header-anchor" href="#track-your-progress" aria-label="Permalink to &quot;Track Your Progress&quot;">​</a></h3><p>Notice:</p><ul><li>When do you feel most in flow?</li><li>What triggers your Inner Critic?</li><li>Which technique helps you most?</li><li>How does your performance change?</li></ul><hr><h2 id="resources-next-steps" tabindex="-1">Resources &amp; Next Steps <a class="header-anchor" href="#resources-next-steps" aria-label="Permalink to &quot;Resources &amp; Next Steps&quot;">​</a></h2><h3 id="continue-learning" tabindex="-1">Continue Learning <a class="header-anchor" href="#continue-learning" aria-label="Permalink to &quot;Continue Learning&quot;">​</a></h3><ul><li><strong>The Zone</strong> - Deep dive into flow states</li><li><strong>Mental Strength</strong> - Advanced pressure management</li><li><strong>Goal Template</strong> - Structure your development</li><li><strong>Diary Template</strong> - Track your progress</li></ul><h3 id="practice-daily" tabindex="-1">Practice Daily <a class="header-anchor" href="#practice-daily" aria-label="Permalink to &quot;Practice Daily&quot;">​</a></h3><ul><li>5 minutes of mindful breathing</li><li>Visualize successful shots</li><li>Practice your pre-shot routine</li><li>Reframe negative thoughts</li></ul><hr><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ol><li><strong>Flow state is accessible</strong> - You can learn to enter it more consistently</li><li><strong>Your inner voice matters</strong> - Coach yourself, don&#39;t criticize</li><li><strong>Simple tools work</strong> - 3 breaths, a routine, a reset</li><li><strong>Practice is key</strong> - Mental skills need training like technical skills</li></ol><hr><p><strong>Remember:</strong> Mental training is not about positive thinking. It&#39;s about practical techniques that help you access your best performance under pressure.</p><hr><p><em>Visit carreau.app for more resources</em><br><em>Pétanque Academy - Elite Player Development</em></p>',61)])])}]]);export{i as __pageData,r as default};
